  var ln = edgeGroup.line(u[0], u[1], v[0], v[1]).stroke({ color: '#000', width: 1.2 });
  ln.css('cursor', 'pointer');
  (function (k, w, uu, vv) {
    ln.on('click', function () {
      var inTree = TREES[curTree].indexOf(k) >= 0;
      var msg = inTree
        ? 'Edge ' + uu + '-' + vv + ' (weight ' + w + ') is IN the shaded spanning tree — removing it would split the tree in two.'
        : 'Edge ' + uu + '-' + vv + ' (weight ' + w + ') is excluded: the tree already connects ' + uu + ' and ' + vv + ' through cheaper edges, so adding it would close a cycle and raise the total.';
      document.getElementById('edgeInfo').textContent = uu + '-' + vv + ' (w=' + w + '): ' + (inTree ? 'in tree' : 'excluded');
      showPopup('Edge ' + uu + '-' + vv + ' (w = ' + w + ')', msg);
    });
    ln.on('mousemove', function (ev) { showTooltip(uu + '-' + vv + ': weight ' + w, ev); });
    ln.on('mouseleave', hideTooltip);
  })(k, e[2], e[0], e[1]);
  edgeEls[k] = ln;
});

// ── Weight labels ───────────────────────────────────────────────────────────
var LABEL_OFF = { 'a-b': [-12, -10], 'b-c': [0, -14], 'c-d': [0, -14], 'd-e': [12, -8],
  'a-h': [-14, 10], 'b-h': [-16, 0], 'h-i': [-6, -12], 'h-g': [0, 18], 'g-i': [10, -10],
  'i-c': [12, -6], 'c-f': [-20, -12], 'g-f': [0, 18], 'd-f': [-18, 0], 'e-f': [14, 10] };
EDGES.forEach(function (e) {
  var u = POS[e[0]], v = POS[e[1]], k = ekey(e[0], e[1]);
  var mx = (u[0] + v[0]) / 2, my = (u[1] + v[1]) / 2;
  var off = LABEL_OFF[k] || [0, -10];
  labelGroup.text(String(e[2])).font({ size: 15, family: 'serif' })
    .center(mx + off[0], my + off[1])
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
});

// ── Vertices ────────────────────────────────────────────────────────────────
Object.keys(POS).forEach(function (name) {
  var p = POS[name];
  var g = nodeGroup.group();
  g.circle(30).center(p[0], p[1]).fill('#e8e8e8').stroke({ color: '#000', width: 1.2 });
  g.text(name).font({ size: 17, family: 'serif', style: 'italic' }).center(p[0], p[1]);
  nodeEls[name] = g;
});

function treeOrder() { return curTree === 'bc' ? BUILD_ORDER : BUILD_ORDER_AH; }

function redrawBands() {
  bandGroup.clear();
  bandEls = {};
  var order = treeOrder();
  TREES[curTree].forEach(function (k) {
    var idx = order.indexOf(k);
    var shown = idx >= 0 && builtCount > idx;
    var parts = k.split('-');
    var u = POS[parts[0]], v = POS[parts[1]]; // object lookup — never call POS(...)
    bandEls[k] = bandGroup.line(u[0], u[1], v[0], v[1])
      .stroke({ color: '#999', width: 12, opacity: shown ? 0.75 : 0, linecap: 'round' });
  });
  bandGroup.back(); // bands below edges/labels/nodes, above white background

  // Dim unreached vertices while building
  var reached = {};
  var ord = treeOrder();
  for (var i = 0; i < Math.min(builtCount, ord.length); i++) {
    var pr = ord[i].split('-'); reached[pr[0]] = true; reached[pr[1]] = true;
  }
  var building = builtCount < ord.length;
  Object.keys(nodeEls).forEach(function (n) {
    nodeEls[n].opacity(building && !reached[n] ? 0.35 : 1);
  });

  // Running total
  var wsum = 0;
  for (var j = 0; j < Math.min(builtCount, ord.length); j++) wsum += edgeWeight(ord[j]);
  document.getElementById('totalReadout').innerHTML =
    'Tree weight: <b>' + wsum + '</b>' + (building ? ' (' + builtCount + '/8 edges)' : '');
}

function toggle_treeChoice(on) {
  curTree = on ? 'ah' : 'bc';
  builtCount = 8;
  document.getElementById('buildBtn').textContent = 'Build tree edge by edge';
  redrawBands();
}

function trigger_buildTree() {
  if (builtCount >= 8) {
    builtCount = 0;
    document.getElementById('buildBtn').textContent = 'Add next edge';
  } else {
    builtCount++;
    if (builtCount >= 8) document.getElementById('buildBtn').textContent = 'Build tree edge by edge';
  }
  redrawBands();
}

var STEPS = [
  { n: 'Nine pins (vertices) must be wired together; each edge weight is the wire cost. The gray band marks one cheapest way to connect all nine — a minimum spanning tree of total weight 37.',
    s: function () { document.getElementById('treeChoiceInput').checked = false; toggle_treeChoice(false); } },
  { n: 'Press "Add next edge" repeatedly: each press adds one gray edge (lightest first), updates the running total, and grows the reached set. Nine vertices, exactly eight edges, no cycle — that is a spanning tree.',
    s: function () { document.getElementById('treeChoiceInput').checked = false; toggle_treeChoice(false); builtCount = 0; document.getElementById('buildBtn').textContent = 'Add next edge'; redrawBands(); } },
  { n: 'Click any thin edge, like b-h (11) or d-f (14): it was left out because the tree already connects its endpoints more cheaply — adding it would create a cycle whose other edges are all lighter.',
    s: function () { builtCount = 8; document.getElementById('buildBtn').textContent = 'Build tree edge by edge'; redrawBands(); } },
  { n: 'Toggle to the alternate tree: b-c (8) drops out and a-h (8) takes its place. The gray band moves, but the total stays 37 — a minimum spanning tree need not be unique.',
    s: function () { document.getElementById('treeChoiceInput').checked = true; toggle_treeChoice(true); } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  document.getElementById('demoNarration').textContent = STEPS[stepIdx].n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  STEPS[stepIdx].s();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

redrawBands();
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

